/* maisim_alvo.c — what the target gives the control (generated by MaiSim). In the SIL, MaiSim had its own version; here, yours:
   - maisim_scope: on the target, nothing (or a log, a DAC to see on the oscilloscope);
   - maisim_envia / maisim_recebeu: messages between controllers — your communication (CAN, SPI, IPC between CPU1 and CPU2…).
     A single controller does not use them: leave them as they are. */
#include "maisim_controle.h"

void maisim_scope(const char *nome, maisim_real valor) {
    (void)nome; (void)valor;
}

void maisim_envia(const char *para, const char *chave, maisim_real valor) {
    (void)para; (void)chave; (void)valor;  /* TODO: send it over your communication */
}

int maisim_recebeu(const char *de, const char *chave, maisim_real *valor) {
    (void)de; (void)chave; (void)valor;    /* TODO: 1 and the value if it arrived in this sample */
    return 0;
}
